/**
 * AzFIT Program Library
 * Pre-built fitness programs for trainers to assign to clients.
 */

export interface LibraryProgram {
  id: string;
  name: string;
  description: string;
  goal: string;
  method: string;
  difficulty: string;
  duration: string;
  durationWeeks?: number;
  frequency: string;
  frequencyPerWeek?: number;
  phases: number;
  tags: string[];
  category?: string;
  equipmentRequired: string[];
  progressionRules: string[];
  estimatedTimePerSession: number;
  totalVolume?: number;
  exercises: LibraryExercise[];
  programStructure?: string;
  progressionModel?: string;
  avgAdherencePct?: number;
  revenueHkd?: number;
  programId?: string;
  timesUsed?: number;
  lastAssigned?: string | null;
  clientSatisfaction?: number;
}

export type ProgramLibraryData = LibraryProgram;

export interface LibraryExercise {
  name: string;
  sets: number;
  reps: string;
  rest: string;
  category: string;
  muscleGroup?: string;
}

