export const PROGRAMS_LIBRARY: LibraryProgram[] = PROGRAMS;

/**
 * Get all programs in the library.
 */
export function getProgramLibrary(): LibraryProgram[] {
  return PROGRAMS;
}

/**
 * Get a single program by its ID.
 */
export function getProgramById(id: string): LibraryProgram | undefined {
  return PROGRAMS.find((p) => p.id === id);
}

/**
 * Filter programs by goal.
 */
export function getProgramsByGoal(goal: string): LibraryProgram[] {
  return PROGRAMS.filter((p) => p.goal === goal);
}

/**
 * Filter programs by difficulty.
 */
export function getProgramsByDifficulty(difficulty: string): LibraryProgram[] {
  return PROGRAMS.filter((p) => p.difficulty === difficulty);
}

/**
 * Search programs by name or tag.
 */
export function searchPrograms(query: string): LibraryProgram[] {
  const q = query.toLowerCase();
  return PROGRAMS.filter(
    (p) =>
      p.name.toLowerCase().includes(q) ||
      p.tags.some((t) => t.toLowerCase().includes(q)) ||
      p.goal.toLowerCase().includes(q)
  );
}
